function Icon({ name, size = 20 }) {
  const common = {
    width: size,
    height: size,
    viewBox: "0 0 24 24",
    fill: "none",
    stroke: "currentColor",
    strokeWidth: 1.7,
    strokeLinecap: "round",
    strokeLinejoin: "round",
    "aria-hidden": true,
  };
  const paths = {
    arrow: <><path d="M5 12h13"/><path d="m13 6 6 6-6 6"/></>,
    instagram: <><rect x="3" y="3" width="18" height="18" rx="5"/><circle cx="12" cy="12" r="4"/><circle cx="17.4" cy="6.7" r=".8" fill="currentColor" stroke="none"/></>,
    phone: <><path d="M7.5 3.5 5.8 4.7a2 2 0 0 0-.8 2.2c1.4 5.4 6.7 10.7 12.1 12.1a2 2 0 0 0 2.2-.8l1.2-1.7a1.7 1.7 0 0 0-.2-2.2l-2.5-2.5a1.7 1.7 0 0 0-2.1-.2l-1.6 1a12.6 12.6 0 0 1-4.5-4.5l1-1.6a1.7 1.7 0 0 0-.2-2.1L9.7 3.9a1.7 1.7 0 0 0-2.2-.4Z"/></>,
    menu: <><path d="M4 7h16"/><path d="M4 12h16"/><path d="M4 17h16"/></>,
    close: <><path d="m6 6 12 12"/><path d="m18 6-12 12"/></>,
    spark: <><path d="m12 2 1.7 6.3L20 10l-6.3 1.7L12 18l-1.7-6.3L4 10l6.3-1.7L12 2Z"/><path d="m19 16 .7 2.3L22 19l-2.3.7L19 22l-.7-2.3L16 19l2.3-.7L19 16Z"/></>,
    lock: <><rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/></>,
    edit: <><path d="M4 20h4L19 9l-4-4L4 16v4Z"/><path d="m13.5 6.5 4 4"/></>,
    reset: <><path d="M4 12a8 8 0 1 0 2.3-5.7"/><path d="M4 5v5h5"/></>,
    external: <><path d="M14 4h6v6"/><path d="M20 4 10 14"/><path d="M18 13v5a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h5"/></>,
    mouse: <><rect x="7" y="3" width="10" height="18" rx="5"/><path d="M12 7v3"/></>,
  };
  return <svg {...common}>{paths[name] || paths.spark}</svg>;
}

function useReveal() {
  useEffect(() => {
    const els = document.querySelectorAll("[data-reveal]");
    const io = new IntersectionObserver(
      entries => entries.forEach(e => e.isIntersecting && e.target.classList.add("is-visible")),
      { threshold: 0.12 }
    );
    els.forEach(el => io.observe(el));
    return () => io.disconnect();
  }, []);
}

function usePointerGlow() {
  useEffect(() => {
    const onMove = e => {
      document.documentElement.style.setProperty("--mx", `${e.clientX}px`);
      document.documentElement.style.setProperty("--my", `${e.clientY}px`);
    };
    window.addEventListener("pointermove", onMove, { passive: true });
    return () => window.removeEventListener("pointermove", onMove);
  }, []);
}

function useTilt() {
  useEffect(() => {
    const cards = [...document.querySelectorAll("[data-tilt]")];
    const handlers = cards.map(card => {
      const move = e => {
        if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
        const r = card.getBoundingClientRect();
        const x = (e.clientX - r.left) / r.width - 0.5;
        const y = (e.clientY - r.top) / r.height - 0.5;
        card.style.setProperty("--rx", `${(-y * 5).toFixed(2)}deg`);
        card.style.setProperty("--ry", `${(x * 6).toFixed(2)}deg`);
        card.style.setProperty("--tz", "8px");
      };
      const leave = () => {
        card.style.setProperty("--rx", "0deg");
        card.style.setProperty("--ry", "0deg");
        card.style.setProperty("--tz", "0px");
      };
      card.addEventListener("pointermove", move);
      card.addEventListener("pointerleave", leave);
      return [card, move, leave];
    });
    return () => handlers.forEach(([card, move, leave]) => {
      card.removeEventListener("pointermove", move);
      card.removeEventListener("pointerleave", leave);
    });
  }, []);
}

function loadDesign() {
  try {
    const raw = localStorage.getItem("matin-portfolio-design");
    return raw ? { ...INITIAL_DESIGN, ...JSON.parse(raw) } : INITIAL_DESIGN;
  } catch {
    return INITIAL_DESIGN;
  }
}

async function sha256(value) {
  const data = new TextEncoder().encode(value);
  const hash = await crypto.subtle.digest("SHA-256", data);
  return [...new Uint8Array(hash)].map(x => x.toString(16).padStart(2, "0")).join("");
}

function AdminPanel({ design, setDesign, onClose }) {
  const [logged, setLogged] = useState(false);
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");

  const login = async e => {
    e.preventDefault();
    const digest = await sha256(password);
    if (digest === "ced475fbffe4955c29e3e09cf0a4e395791883ab05caaa95619c86b1235935d6") {
      setLogged(true);
      setError("");
    } else {
      setError("رمز عبور صحیح نیست.");
    }
  };

  const update = (key, value) => {
    const next = { ...design, [key]: value };
    setDesign(next);
    localStorage.setItem("matin-portfolio-design", JSON.stringify(next));
  };

  const reset = () => {
    setDesign(INITIAL_DESIGN);
    localStorage.setItem("matin-portfolio-design", JSON.stringify(INITIAL_DESIGN));
  };

  return (
    <div className="admin-overlay" role="dialog" aria-modal="true">
      <div className="admin-panel glass">
        <div className="admin-head">
          <div>
            <span className="mini-label"><Icon name="lock" size={14}/> ADMIN MODE</span>
            <h3>{logged ? "ویرایش طراحی سایت" : "ورود مدیر"}</h3>
          </div>
          <button className="icon-btn" onClick={onClose} aria-label="بستن"><Icon name="close"/></button>
        </div>

        {!logged ? (
          <form className="admin-login" onSubmit={login}>
            <p>برای ورود به بخش ویرایش، رمز مدیر را وارد کنید.</p>
            <input
              autoFocus
              type="password"
              value={password}
              onChange={e => setPassword(e.target.value)}
              placeholder="رمز عبور"
            />
            {error && <span className="error">{error}</span>}
            <button className="primary-btn" type="submit"><Icon name="lock"/> ورود به پنل</button>
          </form>
        ) : (
          <div className="controls">
            <div className="control-row">
              <label>رنگ Accent</label>
              <input type="color" value={design.accent} onChange={e => update("accent", e.target.value)} />
            </div>
            <div className="control-row">
              <label>رنگ Accent دوم</label>
              <input type="color" value={design.accent2} onChange={e => update("accent2", e.target.value)} />
            </div>
            <label className="range-label">شفافیت شیشه <b>{Math.round(design.glassOpacity * 100)}%</b></label>
            <input type="range" min="0.04" max="0.18" step="0.01" value={design.glassOpacity} onChange={e => update("glassOpacity", Number(e.target.value))}/>
            <label className="range-label">Blur <b>{design.glassBlur}px</b></label>
            <input type="range" min="8" max="42" step="1" value={design.glassBlur} onChange={e => update("glassBlur", Number(e.target.value))}/>
            <label className="range-label">گردی کارت‌ها <b>{design.radius}px</b></label>
            <input type="range" min="16" max="42" step="1" value={design.radius} onChange={e => update("radius", Number(e.target.value))}/>
            <label className="range-label">شدت Glow <b>{Math.round(design.glow * 100)}%</b></label>
            <input type="range" min="0.08" max="0.55" step="0.01" value={design.glow} onChange={e => update("glow", Number(e.target.value))}/>
            <label className="range-label">شدت Motion <b>{design.motion.toFixed(1)}×</b></label>
            <input type="range" min="0.2" max="1.5" step="0.1" value={design.motion} onChange={e => update("motion", Number(e.target.value))}/>
            <button className="ghost-btn" onClick={reset} type="button"><Icon name="reset"/> بازگردانی طراحی</button>
            <small>تنظیمات در همین مرورگر ذخیره می‌شوند.</small>
          </div>
        )}
      </div>
    </div>
  );
}

